<script setup>
import { inject, onMounted, ref } from "vue"; import { RouterLink } from "vue-router"; import PageHeader from "../components/PageHeader.vue"; import EmptyState from "../components/EmptyState.vue"; import StatusBadge from "../components/StatusBadge.vue";
const props = defineProps({ projectId: String, environmentId: String }); const services = inject("services"); const environment = ref(); const project = ref(); const rows = ref([]);
function status(evaluations) { const result = evaluations[0]?.result; if (!result?.length) return "nao_avaliado"; if (result.some((item) => ["nao_conforme", "erro", "invalido"].includes(item.status))) return "nao_conforme"; return result.some((item) => ["atencao", "manual", "nao_avaliado"].includes(item.status)) ? "nao_avaliado" : "conforme"; }
async function load() { environment.value = await services.repositories.environmentRepository.get(props.environmentId); if (!environment.value) return; project.value = await services.projectService.getProject(environment.value.projectId); rows.value = await Promise.all((await services.projectService.listElements(environment.value.id)).map(async element => ({ element, status: status(await services.evaluationService.listEvaluations(element.id)) }))); }
onMounted(load);
</script>
<template><template v-if="environment"><RouterLink class="back-link" :to="`/projects/${environment.projectId}`">‹ {{ project?.name ?? 'Projeto' }}</RouterLink><PageHeader eyebrow="Ambiente" :title="environment.name" description="Elementos e situação da última avaliação."><template #action><RouterLink class="button" :to="{ path: '/elements/new', query: { environmentId: environment.id } }">+ Adicionar elemento</RouterLink></template></PageHeader><div v-if="rows.length" class="card-list"><RouterLink v-for="row in rows" :key="row.element.id" class="card card--interactive" :to="`/elements/${row.element.id}`"><div class="card__link"><span class="card__icon">◇</span><div><h2>{{ row.element.name }}</h2><p>{{ row.element.type }}</p></div><StatusBadge :status="row.status" /><span class="chevron">›</span></div></RouterLink></div><EmptyState v-else title="Nenhum elemento ainda" text="Cadastre portas, rampas, sanitários e outros itens para avaliar."><RouterLink class="button" :to="{ path: '/elements/new', query: { environmentId: environment.id } }">+ Adicionar elemento</RouterLink></EmptyState></template><EmptyState v-else title="Ambiente não encontrado" text="Ele pode ter sido removido."><RouterLink class="button" to="/projects">Projetos</RouterLink></EmptyState></template>
